    const hotelPrice=`<section class="price-box"><h2>▤ ${labels.payment}</h2><table><thead><tr><th>${labels.description}</th><th>${labels.amount}</th></tr></thead><tbody><tr><td>${labels.roomRate} (${nights} × ${esc(choice.price||money(choice.priceBase||0))} · ${rooms} ${labels.rooms})</td><td>${money(hotelTotal)}</td></tr><tr><td>${labels.fees}</td><td>${labels.notCalculated}</td></tr><tr class="total-row"><td>${labels.total}</td><td>${money(hotelTotal)}</td></tr></tbody></table><p class="demo-note">${labels.hotelNotice}</p></section>`;
