$('#searchForm').addEventListener('click',e=>{const button=e.target.closest('[data-suggestion-index]');if(!button)return;const active=state.activeSuggestions;if(!active)return;const option=active.items[Number(button.dataset.suggestionIndex)];const input=$('#searchForm').elements.namedItem(active.inputName);if(!option||!input)return;if(button.dataset.suggestionType==='airport')selectAirportSuggestion(input,option);else selectHotelSuggestion(input,option)});
document.addEventListener('click',e=>{if(!e.target.closest('.search-form .field'))closeAutocompleteMenus()});
$('#flightTypeOptions').addEventListener('click',e=>{const mode=e.target.closest('[data-trip-type]');if(mode){state.tripType=mode.dataset.tripType;renderFields();return}if(e.target.closest('#addFlightLeg')){const form=$('#searchForm');const draft=Object.fromEntries(new FormData(form).entries());state.multiCityCount=Math.min(5,state.multiCityCount+1);renderFields();for(const [key,value] of Object.entries(draft)){if(form.elements.namedItem(key))form.elements.namedItem(key).value=value}}});
$('#resultsPanel').addEventListener('click',e=>{const filter=e.target.closest('[data-star-filter]');if(filter){state.hotelStars=filter.dataset.starFilter;renderResults();return}const gallery=e.target.closest('[data-hotel-gallery-index]');if(gallery){openHotelGallery(gallery.dataset.hotelGalleryIndex);return}const button=e.target.closest('[data-option-index]');if(!button)return;state.chosen=state.resultOptions[Number(button.dataset.optionIndex)];const amount=state.chosen.priceBase??state.chosen.price;state.chosen.price=amount==null||amount===''?'':formatMoney(amount);openRequestModal()});
$('#hotelGalleryThumbs').addEventListener('click',e=>{const thumb=e.target.closest('[data-gallery-photo-index]');if(!thumb)return;state.galleryPhotoIndex=Number(thumb.dataset.galleryPhotoIndex);renderGalleryPhoto()});
$('#hotelGallery').addEventListener('click',e=>{if(e.target.id==='hotelGallery'){closeHotelGallery();return}if(e.target.closest('.gallery-prev')){state.galleryPhotoIndex=(state.galleryPhotoIndex+HOTEL_GALLERY_PHOTOS.length-1)%HOTEL_GALLERY_PHOTOS.length;renderGalleryPhoto()}if(e.target.closest('.gallery-next')){state.galleryPhotoIndex=(state.galleryPhotoIndex+1)%HOTEL_GALLERY_PHOTOS.length;renderGalleryPhoto()}if(e.target.closest('#chooseGalleryHotel')){state.chosen={...state.galleryHotel,price:formatMoney(state.galleryHotel.priceBase??state.galleryHotel.price)};closeHotelGallery();openRequestModal()}});
$('#serviceTabs').addEventListener('click',e=>{const btn=e.target.closest('[data-service]');if(btn)pickService(btn.dataset.service)});
$$('[data-open-service]').forEach(btn=>btn.addEventListener('click',()=>pickService(btn.dataset.openService,true)));
$('#languageToggle').addEventListener('click',()=>{const language=state.lang==='ar'?'en':'ar';setLanguage(language);window.renderSocialProfiles?.(language)});
$('#currencyToggle').addEventListener('change',e=>{state.currency=e.target.value;$('#currencyCode').textContent=e.target.value;renderResults();if(!$('#hotelGallery').hidden&&state.galleryHotel)openHotelGallery(state.resultOptions.indexOf(state.galleryHotel))});
$('#requestForm').addEventListener('submit',e=>{e.preventDefault();const form=e.currentTarget;if(!form.reportValidity())return;const data=new FormData(form);const rec=makeRequest(data.get('travelerName'),data.get('passportNumber'),data.get('gender'));closeModal();buildPdf(rec);notify(t('requestCreated'))});
$('#closeModal').addEventListener('click',closeModal);$('#requestModal').addEventListener('click',e=>{if(e.target.id==='requestModal')closeModal()});$('#closeHotelGallery').addEventListener('click',closeHotelGallery);document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('#menuToggle').getAttribute('aria-expanded')==='true'){setMenuExpanded(false);$('#menuToggle').focus()}else if(e.key==='Escape'&&!$('#hotelGallery').hidden)closeHotelGallery();else if(e.key==='Escape'&&!$('#requestModal').hidden)closeModal();else trapDialogFocus(e)});$('#ordersButton').addEventListener('click',showRequests);$('#menuToggle').addEventListener('click',()=>setMenuExpanded($('#menuToggle').getAttribute('aria-expanded')!=='true'));$('#mainNav').addEventListener('click',e=>{if(e.target.closest('a'))setMenuExpanded(false)});document.addEventListener('click',e=>{if(!e.target.closest('.site-header')&&$('#menuToggle').getAttribute('aria-expanded')==='true')setMenuExpanded(false)});
setLanguage('ar');updateCount();
